// Keep only conversations whose LAST message is an inbound customer reply
// with real text. Emit one item per reply for classification.
const conv = ($input.first().json.conversations) || [];
const out = [];
for (const c of conv) {
  if (c.lastMessageDirection !== 'inbound') continue;
  const body = (c.lastMessageBody || '').trim();
  if (!body) continue;
  out.push({ json: {
    conversationId: c.id,
    contactId: c.contactId,
    email: c.email || null,
    phone: c.phone || null,
    ts: c.lastMessageDate,            // epoch ms
    body: body.slice(0, 2000)
  }});
}
return out;

// Zip Claude responses with the reply metadata (index-aligned), normalize the
// label, and aggregate counts by month + sentiment for the upsert RPC.
const replies = $('Extract inbound replies').all();
const resps = $input.all();

function norm(t) {
  t = String(t || '').toLowerCase();
  if (t.includes('opt')) return 'Opt-out';
  if (t.includes('posit')) return 'Positive';
  if (t.includes('negat')) return 'Negative';
  return 'Neutral';
}

const counts = {};
for (let i = 0; i < replies.length; i++) {
  const meta = replies[i].json;
  let txt = '';
  try { txt = resps[i].json.content[0].text; } catch (e) { txt = ''; }
  const sentiment = norm(txt);
  const d = new Date(Number(meta.ts));
  const ym = d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0');
  const key = ym + '|' + sentiment;
  counts[key] = (counts[key] || 0) + 1;
}

const rows = Object.entries(counts).map(([k, v]) => {
  const [payout_month, sentiment] = k.split('|');
  return { payout_month, sentiment, reply_count: v };
});

return [{ json: { p_location: 'htgHvVfBZ1WH3UpQoxaa', p_rows: rows } }];
